function j2py(js){var py=js;
py=py.replace(/console\.log\((.*)\);?/g,'print($1)');
py=py.replace(/\b(const|let|var)\s+(\w+)\s*=\s*(.*?);/g,'$2 = $3');
py=py.replace(/function\s+(\w+)\s*\(([^)]*)\)\s*\{/g,'def $1($2):');
py=py.replace(/\breturn\s+(.*?);/g,'return $1');
var lines=py.split('\n');var out=[],ind=0;
lines.forEach(function(l){var t=l.trim();
if(t==='}'||t==='};'){ind=Math.max(0,ind-1);return;}
if(t){out.push('    '.repeat(ind)+t);}if(t.slice(-1)===':')ind++;});
return out.join('\n');}
function j2pyCheck(py){return {hasDef:/^def /m.test(py),hasPrint:/print\(/.test(py),noBraces:py.indexOf('{')<0&&py.indexOf('}')<0};}
